ALTER TABLE jobs ADD COLUMN fetch_null_owned boolean NOT NULL DEFAULT false;
ALTER TABLE jobs ADD COLUMN fetch_null_ambiguous boolean NOT NULL DEFAULT false;
CREATE INDEX jobs_fetch_null_recovery ON jobs(id) WHERE kind='fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NULL AND error IS NOT NULL;
DROP INDEX jobs_unmanaged_problems;
CREATE INDEX jobs_unmanaged_problems ON jobs(kind,item) WHERE kind IS DISTINCT FROM 'read' AND kind IS DISTINCT FROM 'discover' AND problem_code IS DISTINCT FROM 'processor-config' AND NOT (kind IN ('delete','feed-delete') AND coalesce(nullif(problem_code,''),'work-'||kind) IN ('delete','feed-delete','work-delete','work-feed-delete')) AND NOT (kind IS NOT DISTINCT FROM 'fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch') AND NOT fetch_null_ambiguous) AND (problem_code IS NOT NULL OR error IS NOT NULL) AND NOT (kind IS NOT DISTINCT FROM 'download_media' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch')) AND NOT ((kind IS NOT DISTINCT FROM 'filter' OR kind IS NOT DISTINCT FROM 'theses') AND item IS NOT NULL AND item<>'' AND (((problem_code='' OR (problem_code IS NULL AND error IS NOT NULL))) OR (problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch')))) AND NOT (kind IN ('fetch','download_media','filter','theses','delete','feed-delete') AND problem_code IS NOT NULL AND problem_code LIKE 'source-%' AND source_event_owned) AND NOT (kind IS NOT DISTINCT FROM 'fetch' AND problem_code IS NULL AND error IS NOT NULL AND fetch_null_owned);
CREATE INDEX reader_fetch_work_legacy_item_paged ON reader_problems ((md5(substring(coalesce(body::jsonb->>'status_job_identity',identity) FROM ':fetch:(.*)$'))),(md5(id))) WHERE finished IS NULL AND identity LIKE 'job:%' AND body::jsonb->>'code'='work-fetch' AND body::jsonb->>'operation' IN ('producer:fetch','producer:status');
CREATE INDEX state_fetch_null_protected ON state(key COLLATE "C") WHERE key COLLATE "C">='fetch-null-protected:' AND key COLLATE "C"<'fetch-null-protected;';
